package com.tracksphere.domain.model;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="locations") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Location { @Id private UUID id; @Column(name="vehicle_id",nullable=false,length=100) private String vehicleId; @Column(nullable=false) private double latitude; @Column(nullable=false) private double longitude; @Column(name="accuracy_meters") private Double accuracyMeters; @Column(name="recorded_at",nullable=false) private Instant recordedAt; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; public Location(String vehicleId,double latitude,double longitude,Double accuracyMeters,Instant recordedAt){id=UUID.randomUUID();this.vehicleId=vehicleId;this.latitude=latitude;this.longitude=longitude;this.accuracyMeters=accuracyMeters;this.recordedAt=recordedAt==null?Instant.now():recordedAt;createdAt=Instant.now();} }
